// TypeScript — estático
function add(a: number, b: number): number { return a + b; }
add(1, 2);     // ok
add(1, "b");   // erro em compile

// TS é estrutural
interface Named { text: string; }
const u = { text: "Ana", age: 30 };
const n: Named = u;   // OK, mesma forma

// Java é nominal
interface Named { String name(); }
class User { String name() { return "Ana"; } }
Named n = new User();   // erro: User não implements Named

// TS unsound: any abre buraco
const x: any = 42;
const s: string = x;   // compila mas explode em runtime se usar .toUpperCase

// Rust sound: nenhum escape em segurança de memória
fn main() {
    let s = String::from("hi");
    let r = &s;
    drop(s);        // compilador barra: r ainda em uso
    println!("{}", r);
}

